import os
# Find the repo directory
for root, dirs, files in os.walk('/'):
    if 'boltons' in dirs and 'iterutils.py' in files:
        print(f"Found boltons/iterutils.py at: {os.path.join(root, 'boltons', 'iterutils.py')}")
        break
    # Also check for .git
    if '.git' in dirs:
        git_dir = os.path.join(root, '.git')
        if os.path.isdir(git_dir):
            print(f"Git repo found at: {root}")
